var i=`cost-benefit-analysis`;var o=102;var n={en:[{id:`T102-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Cost–Benefit Analysis`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Amdahl's Law bounds the speedup of a workload when only part can be parallelized.`},{id:`B`,text:`Conway's Law observes that system designs tend to reflect the communication structures of the organizations creating them.`},{id:`C`,text:`Cost–benefit analysis estimates whether expected business value justifies implementation, maintenance and risk.`},{id:`D`,text:`Brooks's Law warns that adding people to a late software project may make it later because onboarding and communication cost time.`}]},{id:`T102-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Cost–Benefit Analysis`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Write short decision records near the code, including assumptions, constraints, decision drivers, rejected options and review triggers.`},{id:`B`,text:`Compare required customization, vendor reliability, security/compliance, integration effort, exit costs, data ownership and long-term support.`},{id:`C`,text:`Estimate upfront effort, ongoing operations, avoided incidents, delivery acceleration and opportunity cost.`},{id:`D`,text:`Rank performance bottlenecks, incident sources, customer complaints or feature adoption using real data.`}]},{id:`T102-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`Replacing a manual invoice export with automation may cost two weeks initially but save several hours weekly and reduce errors.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Factor in support, edge cases and reliability of the automation.`},{id:`B`,text:`A small cross-functional team owning reservations end-to-end can reduce those coordination costs.`},{id:`C`,text:`Independent test automation may be more parallelizable.`},{id:`D`,text:`Increasing upload workers only grows the queue; parallelizing or optimizing OCR may improve completion throughput.`}]},{id:`T102-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Cost–Benefit Analysis`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Buying is not zero engineering; vendor contracts, outages and migrations are part of the system.`},{id:`B`,text:`Avoid 'best practice' answers without context.`},{id:`C`,text:`Benefits such as developer happiness or lower risk are real but hard to monetize; document them explicitly.`},{id:`D`,text:`The law is contextual, not an excuse to understaff a project.`}]},{id:`T102-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It makes assumptions visible and helps compare engineering investments fairly.`}]}]},{id:`T102-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`An option with the lowest initial price always has the lowest total cost.`}]}]},{id:`T102-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`A low initial quote can hide long-term licensing or integration costs.`}]}]},{id:`T102-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Cost–Benefit Analysis`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Estimate upfront effort, ongoing operations, avoided incidents, delivery acceleration and opportunity cost.`},{id:`B`,text:`Expected maintenance and exit costs should be excluded from economic analysis.`},{id:`C`,text:`Adding developers to a late project always reduces remaining delivery time.`},{id:`D`,text:`Cost–benefit analysis estimates whether expected business value justifies implementation, maintenance and risk.`}]},{id:`T102-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Cost–Benefit Analysis`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`An option with the lowest initial price always has the lowest total cost.`},{id:`B`,text:`A low initial quote can hide long-term licensing or integration costs.`},{id:`C`,text:`Factor in support, edge cases and reliability of the automation.`},{id:`D`,text:`Decision records should omit rejected alternatives and review triggers.`}]},{id:`T102-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`Replacing a manual invoice export with automation may cost two weeks initially but save several hours weekly and reduce errors.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to create a build/buy matrix for authentication, email and booking rules, with vendor exit plans and three-year total-cost ranges.`},{id:`B`,text:`Ask an agent to propose a staffing and task-splitting plan for a late MVP, separating critical-path work from independent work and explicit onboarding costs.`},{id:`C`,text:`Ask an agent to estimate three automation options using low, base and high scenarios, including operating costs and a break-even point.`},{id:`D`,text:`Ask an agent to compare two architectures for a booking service with a weighted decision matrix, failure scenarios, assumptions and an ADR-style recommendation.`}]},{id:`T102-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Which uncertain assumption dominates whether the investment is worthwhile?`}]}]},{id:`T102-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`Replacing a manual invoice export with automation may cost two weeks initially but save several hours weekly and reduce errors.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Cost–Benefit Analysis`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T102-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`Replacing a manual invoice export with automation may cost two weeks initially but save several hours weekly and reduce errors.`,b:!0},{t:` — propose three checks for `},{t:`Cost–Benefit Analysis`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T102-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`Replacing a manual invoice export with automation may cost two weeks initially but save several hours weekly and reduce errors.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T102-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Cost–Benefit Analysis`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`Replacing a manual invoice export with automation may cost two weeks initially but save several hours weekly and reduce errors.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T102-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Аналіз витрат і вигод`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Закон Амдала обмежує прискорення програми, коли лише частину можна розпаралелити.`},{id:`B`,text:`Закон Конвея описує тенденцію систем відображати комунікаційну структуру організацій, які їх створюють.`},{id:`C`,text:`Аналіз витрат і вигод оцінює, чи виправдовує очікувана користь реалізацію, підтримку й ризик.`},{id:`D`,text:`Закон Брукса попереджає, що додавання людей до запізнілого проєкту може ще більше затримати його через навчання та комунікацію.`}]},{id:`T102-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Аналіз витрат і вигод`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Пишіть короткі записи поруч із кодом: припущення, обмеження, критерії, відхилені альтернативи й умови перегляду.`},{id:`B`,text:`Порівнюйте кастомізацію, надійність постачальника, безпеку й вимоги, інтеграцію, вартість виходу, власність на дані та підтримку.`},{id:`C`,text:`Оцініть стартову працю, експлуатаційні витрати, уникнені інциденти, прискорення релізів і альтернативну вартість.`},{id:`D`,text:`Ранжуйте вузькі місця, причини інцидентів, скарги чи використання фіч за даними.`}]},{id:`T102-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Автоматизація ручного експорту рахунків може коштувати два тижні розробки, але щотижня економити години й зменшувати помилки.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Врахуйте підтримку, винятки й надійність процесу.`},{id:`B`,text:`Невелика кросфункціональна команда, що відповідає за бронювання наскрізно, зменшує витрати координації.`},{id:`C`,text:`Незалежна автоматизація тестів може бути кращою паралельною задачею.`},{id:`D`,text:`Додавання upload-воркерів лише збільшує чергу; оптимізація OCR може підвищити загальну пропускну здатність.`}]},{id:`T102-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Аналіз витрат і вигод`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Купівля не означає нуль інженерної роботи: контракти, збої постачальника й міграції стають частиною системи.`},{id:`B`,text:`Уникайте «найкращих практик» без контексту.`},{id:`C`,text:`Переваги на кшталт задоволення команди чи зниження ризику реальні, хоча їх важко оцінити грошима; фіксуйте їх.`},{id:`D`,text:`Закон контекстний і не виправдовує нестачу людей.`}]},{id:`T102-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Він робить припущення явними та допомагає порівнювати інвестиції.`}]}]},{id:`T102-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Варіант із найнижчою стартовою ціною завжди має найнижчу загальну вартість.`}]}]},{id:`T102-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Низька стартова ціна може приховувати ліцензії й інтеграції.`}]}]},{id:`T102-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Аналіз витрат і вигод`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Оцініть стартову працю, експлуатаційні витрати, уникнені інциденти, прискорення релізів і альтернативну вартість.`},{id:`B`,text:`Очікувану підтримку та вартість виходу потрібно виключати з економічного аналізу.`},{id:`C`,text:`Додавання розробників у запізнілий проєкт завжди скорочує термін завершення.`},{id:`D`,text:`Аналіз витрат і вигод оцінює, чи виправдовує очікувана користь реалізацію, підтримку й ризик.`}]},{id:`T102-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Аналіз витрат і вигод`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Варіант із найнижчою стартовою ціною завжди має найнижчу загальну вартість.`},{id:`B`,text:`Низька стартова ціна може приховувати ліцензії й інтеграції.`},{id:`C`,text:`Врахуйте підтримку, винятки й надійність процесу.`},{id:`D`,text:`Записи рішень мають пропускати відхилені альтернативи й умови перегляду.`}]},{id:`T102-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Автоматизація ручного експорту рахунків може коштувати два тижні розробки, але щотижня економити години й зменшувати помилки.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента скласти матрицю build/buy для входу, пошти та правил бронювання з планом виходу від постачальника й трирічною оцінкою витрат.`},{id:`B`,text:`Попросіть агента запропонувати розподіл людей і задач для запізнілого MVP, відділивши критичний шлях від паралельних робіт і вартості онбордингу.`},{id:`C`,text:`Попросіть агента оцінити три способи автоматизації за песимістичним, базовим та оптимістичним сценаріями з експлуатаційними витратами й точкою окупності.`},{id:`D`,text:`Попросіть агента порівняти дві архітектури бронювання через матрицю критеріїв, сценарії збоїв, припущення й рішення у форматі ADR.`}]},{id:`T102-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Яке невизначене припущення найбільше впливає на окупність інвестиції?`}]}]},{id:`T102-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Автоматизація ручного експорту рахунків може коштувати два тижні розробки, але щотижня економити години й зменшувати помилки.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Аналіз витрат і вигод`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T102-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Автоматизація ручного експорту рахунків може коштувати два тижні розробки, але щотижня економити години й зменшувати помилки.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Аналіз витрат і вигод`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T102-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Автоматизація ручного експорту рахунків може коштувати два тижні розробки, але щотижня економити години й зменшувати помилки.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T102-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Аналіз витрат і вигод`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Автоматизація ручного експорту рахунків може коштувати два тижні розробки, але щотижня економити години й зменшувати помилки.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var s={slug:i,topicId:102,questions:n};export{s as default,n as questions,i as slug,o as topicId};